import com.google.javascript.rhino.IR;
import com.google.javascript.rhino.Node;
import org.junit.Test;

import static org.junit.Assert.*;

public class IRTryCatchTest {

    @Test
    public void testTryCatchBasic() {
        Node tryBlock = IR.block();
        Node catchNode = IR.catchNode(IR.name("e"), IR.block());
        Node tryCatchNode = IR.tryCatch(tryBlock, catchNode);

        assertNotNull(tryCatchNode);
        assertEquals(Node.TRY, tryCatchNode.getType());
        assertEquals(2, tryCatchNode.getChildCount());
        assertEquals(tryBlock, tryCatchNode.getFirstChild());
        assertEquals(catchNode, tryCatchNode.getLastChild());
        assertEquals(tryBlock.getType(), tryCatchNode.getFirstChild().getType());
        assertEquals(catchNode.getType(), tryCatchNode.getLastChild().getType());
    }

    @Test
    public void testTryCatchWithContent() {
        Node statementInTry = IR.exprResult(IR.string("hello"));
        Node tryBlock = IR.block(statementInTry);

        Node exceptionVar = IR.name("error");
        Node statementInCatch = IR.exprResult(IR.string("caught"));
        Node catchNode = IR.catchNode(exceptionVar, IR.block(statementInCatch));

        Node tryCatchNode = IR.tryCatch(tryBlock, catchNode);

        assertNotNull(tryCatchNode);
        assertEquals(Node.TRY, tryCatchNode.getType());
        assertEquals(2, tryCatchNode.getChildCount());

        Node actualTryBlock = tryCatchNode.getFirstChild();
        Node actualCatchNode = tryCatchNode.getLastChild();

        assertEquals(tryBlock, actualTryBlock);
        assertEquals(catchNode, actualCatchNode);

        assertEquals(1, actualTryBlock.getChildCount());
        assertEquals(statementInTry, actualTryBlock.getFirstChild());

        assertEquals(exceptionVar, actualCatchNode.getFirstChild()); // The exception variable
        assertEquals(IR.block(statementInCatch), actualCatchNode.getLastChild()); // The catch block
    }

    @Test(expected = NullPointerException.class)
    public void testTryCatchNullTryBody() {
        Node catchNode = IR.catchNode(IR.name("e"), IR.block());
        IR.tryCatch(null, catchNode);
    }

    @Test(expected = NullPointerException.class)
    public void testTryCatchNullCatchNode() {
        Node tryBlock = IR.block();
        IR.tryCatch(tryBlock, null);
    }

    @Test(expected = NullPointerException.class)
    public void testTryCatchBothNull() {
        IR.tryCatch(null, null);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryCatchTryBodyNotBlock() {
        Node tryBody = IR.string("not a block"); // Not a BLOCK node
        Node catchNode = IR.catchNode(IR.name("e"), IR.block());
        IR.tryCatch(tryBody, catchNode);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryCatchCatchNodeNotCatch() {
        Node tryBlock = IR.block();
        Node catchNode = IR.string("not a catch"); // Not a CATCH node
        IR.tryCatch(tryBlock, catchNode);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryCatchBothInvalidType() {
        Node tryBody = IR.number(123); // Not a BLOCK node
        Node catchNode = IR.name("invalid"); // Not a CATCH node
        IR.tryCatch(tryBody, catchNode);
    }

    @Test
    public void testTryCatchAttributes() {
        Node tryBlock = new Node(Node.BLOCK, 10, 5);
        Node catchNode = new Node(Node.CATCH, 20, 10);
        Node tryCatchNode = IR.tryCatch(tryBlock, catchNode);

        assertNotNull(tryCatchNode);
        assertEquals(Node.TRY, tryCatchNode.getType());
        // IR.tryCatch doesn't inherently set line/char numbers based on children
        // It's usually set by a higher-level parsing/building process.
        // For this method, we only ensure the type and children are correct.
        assertEquals(tryBlock, tryCatchNode.getFirstChild());
        assertEquals(catchNode, tryCatchNode.getLastChild());
    }

    @Test
    public void testTryCatchWithEmptyChildren() {
        Node emptyBlock = IR.block();
        Node emptyCatch = IR.catchNode(IR.name("ex"), IR.block());

        Node tryCatchNode = IR.tryCatch(emptyBlock, emptyCatch);

        assertNotNull(tryCatchNode);
        assertEquals(Node.TRY, tryCatchNode.getType());
        assertEquals(2, tryCatchNode.getChildCount());
        assertEquals(emptyBlock, tryCatchNode.getFirstChild());
        assertEquals(emptyCatch, tryCatchNode.getLastChild());
    }
}
