import com.google.javascript.rhino.IR;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import org.junit.Test;

import static org.junit.Assert.*;

public class IRTryFinallyTest {

    @Test
    public void testTryFinallyBasic() {
        Node tryBody = IR.block(IR.exprResult(IR.string("try statement")));
        Node finallyBody = IR.block(IR.exprResult(IR.string("finally statement")));

        Node tryFinallyNode = IR.tryFinally(tryBody, finallyBody);

        assertNotNull(tryFinallyNode);
        assertEquals(Token.TRY, tryFinallyNode.getType());
        assertEquals(2, tryFinallyNode.getChildCount());

        Node firstChild = tryFinallyNode.getFirstChild();
        Node secondChild = tryFinallyNode.getChildAtIndex(1);

        // The first child should be the try block
        assertNotNull(firstChild);
        assertEquals(Token.BLOCK, firstChild.getType());
        assertEquals(tryBody, firstChild); // Should be the exact same Node instance

        // The second child should be the finally block
        assertNotNull(secondChild);
        assertEquals(Token.BLOCK, secondChild.getType());
        assertEquals(finallyBody, secondChild); // Should be the exact same Node instance

        // Ensure there is no catch block (which would be a third child if present in try-catch-finally)
        assertNull(tryFinallyNode.getChildAtIndex(2));
    }

    @Test
    public void testTryFinallyWithEmptyBlocks() {
        Node emptyTryBody = IR.block();
        Node emptyFinallyBody = IR.block();

        Node tryFinallyNode = IR.tryFinally(emptyTryBody, emptyFinallyBody);

        assertNotNull(tryFinallyNode);
        assertEquals(Token.TRY, tryFinallyNode.getType());
        assertEquals(2, tryFinallyNode.getChildCount());

        Node firstChild = tryFinallyNode.getFirstChild();
        Node secondChild = tryFinallyNode.getChildAtIndex(1);

        assertNotNull(firstChild);
        assertEquals(Token.BLOCK, firstChild.getType());
        assertEquals(0, firstChild.getChildCount());
        assertEquals(emptyTryBody, firstChild);

        assertNotNull(secondChild);
        assertEquals(Token.BLOCK, secondChild.getType());
        assertEquals(0, secondChild.getChildCount());
        assertEquals(emptyFinallyBody, secondChild);
    }

    @Test(expected = NullPointerException.class)
