                IR.exprResult(IR.call(IR.name("doSomething"))),
                IR.ifNode(IR.trueNode(), IR.exprResult(IR.string("condition met")))
        );
        Node finallyBody = IR.block(
                IR.exprResult(IR.call(IR.name("cleanup"))),
                IR.returnNode(IR.number(0))
        );

        Node tryFinallyNode = IR.tryFinally(tryBody, finallyBody);

        assertNotNull(tryFinallyNode);
        assertEquals(Token.TRY, tryFinallyNode.getType());
        assertEquals(2, tryFinallyNode.getChildCount());

