        assertTrue(tryFinallyNode.isTry());
        assertFalse(tryFinallyNode.isCatch());
        assertFalse(tryFinallyNode.isFinally()); // The try node itself is not a 'finally' node
        assertTrue(tryFinallyNode.hasChildren());
        assertFalse(tryFinallyNode.isLeaf());
    }
