        Node root = new Node(Token.SCRIPT);
        root.addChildToBack(Node.newString(Token.VAR, "testVar"));
        root.addChildToBack(Node.newString(Token.ASSIGN));
        root.addChildToBack(Node.newNumber(10));
        root.addChildToBack(Node.newString(Token.NAME, "testVar"));
        root.addChildToBack(Node.newString(Token.EXPR_RESULT));

        compiler.toSource(mockCodeBuilder, 0, root);

        // Verify that append is called at least once
        verify(mockCodeBuilder, atLeastOnce()).append(anyString());
