import org.apache.commons.compress.utils.ArchiveUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class ArchiveUtilsSanitizeTest {

    @Test
    public void testSanitizeNullInput() {
        assertNull(ArchiveUtils.sanitize(null));
    }

    @Test
    public void testSanitizeEmptyString() {
        assertEquals("", ArchiveUtils.sanitize(""));
    }

    @Test
    public void testSanitizeNoProblematicCharacters() {
        assertEquals("HelloWorld123_abc", ArchiveUtils.sanitize("HelloWorld123_abc"));
        assertEquals("日本語", ArchiveUtils.sanitize("日本語"));
        assertEquals("A B C", ArchiveUtils.sanitize("A B C"));
    }

    @Test
    public void testSanitizeIsoControlCharacters() {
        // U+0000-U+001F
        assertEquals("?", ArchiveUtils.sanitize("\u0000"));
        assertEquals("?", ArchiveUtils.sanitize("\u0001"));
        assertEquals("?", ArchiveUtils.sanitize("\u001F"));
        assertEquals("A?B?C", ArchiveUtils.sanitize("A\u0001B\u001FC"));

        // U+007F-U+009F
        assertEquals("?", ArchiveUtils.sanitize("\u007F")); // DEL
        assertEquals("?", ArchiveUtils.sanitize("\u0080")); // PAD
        assertEquals("?", ArchiveUtils.sanitize("\u009F")); // APC
        assertEquals("X?Y?Z", ArchiveUtils.sanitize("X\u007FY\u0080Z"));
    }

    @Test
    public void testSanitizeSpecialsUnicodeBlock() {
        // U+FFF0-U+FFFF (SPECIALS block)
        assertEquals("?", ArchiveUtils.sanitize("\uFFF0")); // Object Replacement Character
        assertEquals("?", ArchiveUtils.sanitize("\uFFFD")); // Replacement Character
        assertEquals("?", ArchiveUtils.sanitize("\uFFFF")); // Undefined
        assertEquals("1?2?3", ArchiveUtils.sanitize("1\uFFF02\uFFFD3"));
    }

    @Test
    public void testSanitizeFilesystemInvalidCharacters() {
        assertEquals("?", ArchiveUtils.sanitize("/"));
        assertEquals("?", ArchiveUtils.sanitize("\\"));
        assertEquals("?", ArchiveUtils.sanitize(":"));
        assertEquals("?", ArchiveUtils.sanitize("*"));
        assertEquals("?", ArchiveUtils.sanitize("?"));
        assertEquals("?", ArchiveUtils.sanitize("\""));
        assertEquals("?", ArchiveUtils.sanitize("<"));
        assertEquals("?", ArchiveUtils.sanitize(">"));
        assertEquals("?", ArchiveUtils.sanitize("|"));
        assertEquals("file?name", ArchiveUtils.sanitize("file/name"));
        assertEquals("path?to?file", ArchiveUtils.sanitize("path\\to\\file"));
        assertEquals("archive?tar?gz", ArchiveUtils.sanitize("archive:tar.gz"));
        assertEquals("image?", ArchiveUtils.sanitize("image*"));
        assertEquals("query_param?", ArchiveUtils.sanitize("query_param?"));
        assertEquals("quote?", ArchiveUtils.sanitize("quote\""));
        assertEquals("less?than", ArchiveUtils.sanitize("less<than"));
        assertEquals("greater?than", ArchiveUtils.sanitize("greater>than"));
        assertEquals("pipe?", ArchiveUtils.sanitize("pipe|"));
    }

    @Test
    public void testSanitizeMixedProblematicCharacters() {
        String input = "file/name\u0000with:specials\uFFFDand?controls\u007F";
        String expected = "file?name?with?specials?and?controls?";
        assertEquals(expected, ArchiveUtils.sanitize(input));
    }

    @Test
    public void testSanitizeSurrogatePairs() {
        // A Unicode character that is represented by a surrogate pair (e.g., U+1F600 GRINNING FACE)
        String grinningFace = new String(Character.toChars(0x1F600)); // U+1F600
        assertEquals(grinningFace, ArchiveUtils.sanitize(grinningFace));

        // Surrogate pair combined with a problematic character
        String inputWithSurrogateAndProblematic = grinningFace + "/" + new String(Character.toChars(0x1F601));
        String expectedWithSurrogateAndProblematic = grinningFace + "?" + new String(Character.toChars(0x1F601));
        assertEquals(expectedWithSurrogateAndProblematic, ArchiveUtils.sanitize(inputWithSurrogateAndProblematic));

        // Problematic character within a surrogate pair context (should be replaced as a single code point)
        String mixedSurrogateAndControl = "A" + "\u001F" + grinningFace + "\u007F" + "B";
        assertEquals("A?" + grinningFace + "?" + "B", ArchiveUtils.sanitize(mixedSurrogateAndControl));
    }

    @Test
    public void testSanitizeLongStringWithVariousCharacters() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 1000; i++) {
            sb.append("abc");
            if (i % 10 == 0) {
                sb.append("/");
            }
            if (i % 15 == 0) {
                sb.append("\u0001");
            }
            if (i % 20 == 0) {
                sb.append("\uFFFD");
            }
        }
        String input = sb.toString();
        String sanitized = ArchiveUtils.sanitize(input);
        assertNotNull(sanitized);
        assertFalse(sanitized.contains("/"));
        assertFalse(sanitized.contains("\u0001"));
        assertFalse(sanitized.contains("\uFFFD"));
        assertTrue(sanitized.contains("?"));
        assertEquals(input.length(), sanitized.length()); // For simplicity, assuming 1 char replacement for 1 char problematic
    }

    @Test
    public void testSanitizeCharactersAdjacentToProblematic() {
        assertEquals("A?B", ArchiveUtils.sanitize("A/B"));
        assertEquals("A??B", ArchiveUtils.sanitize("A\u0000\u0001B"));
        assertEquals("A?B?", ArchiveUtils.sanitize("A/B\uFFF0"));
    }

    @Test
    public void testSanitizeOnlyProblematicCharacters() {
        assertEquals("????", ArchiveUtils.sanitize("/\\:?"));
        assertEquals("????", ArchiveUtils.sanitize("\u0000\u007F\uFFF0*"));
    }
}
