    public void testWriteNumberBigDecimalNull() throws IOException {
        tokenBuffer.writeNumber((BigDecimal) null);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NULL, parser.nextToken());
        assertNull(parser.getDecimalValue());
        assertEquals(JsonToken.VALUE_NULL, tokenBuffer._first.type(0));
        assertNull(tokenBuffer._first.get(0));
    }

