        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getDecimalValue());
        assertEquals(TokenBuffer.Segment.RAW_TOKEN_BD_NUMBER, tokenBuffer._first.rawType(0));
        assertEquals(value, tokenBuffer._first.get(0));
    }

