import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TokenBufferWriteNumberFloatTest {

    private TokenBuffer tokenBuffer;
    private ObjectCodec mockCodec;

    @Before
    public void setUp() {
        mockCodec = mock(ObjectCodec.class);
        tokenBuffer = new TokenBuffer(mockCodec);
    }

    @Test
    public void testWriteNumberFloatPositive() throws IOException {
        float value = 123.45f;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getFloatValue(), 0.001f);
        assertEquals(String.valueOf(value), parser.getText());
        assertEquals(JsonParser.NumberType.FLOAT, parser.getNumberType());
        assertEquals(value, parser.getNumberValue());
        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteNumberFloatNegative() throws IOException {
        float value = -67.89f;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getFloatValue(), 0.001f);
        assertEquals(String.valueOf(value), parser.getText());
        assertEquals(JsonParser.NumberType.FLOAT, parser.getNumberType());
        assertEquals(value, parser.getNumberValue());
        assertNull(parser.nextToken());
    }

