    public void testWriteNumberFloatMax() throws IOException {
        float value = Float.MAX_VALUE;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getFloatValue(), 0.001f);
        assertEquals(String.valueOf(value), parser.getText());
        assertEquals(JsonParser.NumberType.FLOAT, parser.getNumberType());
        assertEquals(value, parser.getNumberValue());
        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteNumberFloatMin() throws IOException {
        float value = Float.MIN_VALUE;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getFloatValue(), 0.001f);
        assertEquals(String.valueOf(value), parser.getText());
        assertEquals(JsonParser.NumberType.FLOAT, parser.getNumberType());
        assertEquals(value, parser.getNumberValue());
        assertNull(parser.nextToken());
    }

