        assertEquals(JsonParser.NumberType.FLOAT, parser.getNumberType());
        assertEquals(value, parser.getNumberValue());
        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteNumberFloatMultipleTimes() throws IOException {
        float value1 = 1.1f;
        float value2 = 2.2f;
        float value3 = 3.3f;

        tokenBuffer.writeNumber(value1);
        tokenBuffer.writeNumber(value2);
        tokenBuffer.writeNumber(value3);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value1, parser.getFloatValue(), 0.001f);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value2, parser.getFloatValue(), 0.001f);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value3, parser.getFloatValue(), 0.001f);

        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteNumberFloatWithOtherTokens() throws IOException {
        float value = 9.87f;
        String text = "hello";
        int intValue = 123;

        tokenBuffer.writeStartObject();
        tokenBuffer.writeFieldName("floatValue");
        tokenBuffer.writeNumber(value);
        tokenBuffer.writeFieldName("stringValue");
        tokenBuffer.writeString(text);
        tokenBuffer.writeFieldName("intValue");
        tokenBuffer.writeNumber(intValue);
        tokenBuffer.writeEndObject();

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("floatValue", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getFloatValue(), 0.001f);

        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("stringValue", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals(text, parser.getText());

        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("intValue", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(intValue, parser.getIntValue());

        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteNumberFloatForceUseOfBigDecimal() throws IOException {
        tokenBuffer.forceUseOfBigDecimal(true);
        float value = 123.45f;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        // Even if forceUseOfBigDecimal is true, float will still be stored as float,
        // but getNumberValue() might return BigDecimal
        assertEquals(value, parser.getFloatValue(), 0.001f);
        assertEquals(new BigDecimal(String.valueOf(value)), parser.getDecimalValue());
        assertEquals(JsonParser.NumberType.BIG_DECIMAL, parser.getNumberType());
        assertEquals(new BigDecimal(String.valueOf(value)), parser.getNumberValue());
        assertNull(parser.nextToken());
    }

