import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.TreeMap;

import static org.junit.Assert.*;

public class TokenBufferWriteNumberDoubleTest {

    private TokenBuffer tokenBuffer;
    private ObjectCodec objectCodec;

    @Before
    public void setUp() {
        objectCodec = new ObjectMapper();
        tokenBuffer = new TokenBuffer(objectCodec);
    }

    @Test
    public void testWritePositiveDouble() throws IOException {
        double value = 123.456;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getDoubleValue(), 0.001);
        assertEquals(Double.valueOf(value), parser.getNumberValue());
        assertEquals(JsonParser.NumberType.DOUBLE, parser.getNumberType());
        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteNegativeDouble() throws IOException {
        double value = -789.012;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getDoubleValue(), 0.001);
        assertEquals(Double.valueOf(value), parser.getNumberValue());
        assertEquals(JsonParser.NumberType.DOUBLE, parser.getNumberType());
        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteZeroDouble() throws IOException {
        double value = 0.0;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getDoubleValue(), 0.001);
        assertEquals(Double.valueOf(value), parser.getNumberValue());
        assertEquals(JsonParser.NumberType.DOUBLE, parser.getNumberType());
        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteNaN() throws IOException {
        double value = Double.NaN;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertTrue(Double.isNaN(parser.getDoubleValue()));
        assertTrue(Double.isNaN((Double) parser.getNumberValue()));
        assertEquals(JsonParser.NumberType.DOUBLE, parser.getNumberType());
        assertNull(parser.nextToken());
    }

    @Test
    public void testWritePositiveInfinity() throws IOException {
        double value = Double.POSITIVE_INFINITY;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertTrue(Double.isInfinite(parser.getDoubleValue()));
        assertTrue(parser.getDoubleValue() > 0);
        assertEquals(Double.valueOf(value), parser.getNumberValue());
        assertEquals(JsonParser.NumberType.DOUBLE, parser.getNumberType());
        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteNegativeInfinity() throws IOException {
        double value = Double.NEGATIVE_INFINITY;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertTrue(Double.isInfinite(parser.getDoubleValue()));
        assertTrue(parser.getDoubleValue() < 0);
        assertEquals(Double.valueOf(value), parser.getNumberValue());
        assertEquals(JsonParser.NumberType.DOUBLE, parser.getNumberType());
        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteMultipleDoubles() throws IOException {
        double value1 = 1.1;
        double value2 = 2.2;
        double value3 = 3.3;

        tokenBuffer.writeNumber(value1);
        tokenBuffer.writeNumber(value2);
        tokenBuffer.writeNumber(value3);

        JsonParser parser = tokenBuffer.asParser();

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value1, parser.getDoubleValue(), 0.001);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value2, parser.getDoubleValue(), 0.001);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value3, parser.getDoubleValue(), 0.001);

        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteDoubleFollowedByOtherToken() throws IOException {
        double value = 123.45;
        String text = "test";

        tokenBuffer.writeNumber(value);
        tokenBuffer.writeString(text);

        JsonParser parser = tokenBuffer.asParser();

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getDoubleValue(), 0.001);

        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals(text, parser.getText());

        assertNull(parser.nextToken());
    }

    @Test
    public void testTokenBufferWithNoCodec() throws IOException {
        tokenBuffer = new TokenBuffer(null);
        double value = 123.456;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(value, parser.getDoubleValue(), 0.001);
        assertNull(parser.nextToken());
    }

    @Test
    public void testTokenBufferWithNativeIds() throws IOException {
        tokenBuffer = new TokenBuffer(objectCodec, true);
        tokenBuffer.writeObjectId("obj123");
        tokenBuffer.writeTypeId("typeXYZ");
        double value = 42.123;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals("obj123", parser.getObjectId());
        assertEquals("typeXYZ", parser.getTypeId());
        assertEquals(value, parser.getDoubleValue(), 0.001);
        assertNull(parser.nextToken());
    }
