import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;

public class TokenBufferWriteNumberShortTest {

    private TokenBuffer tokenBuffer;
    private ObjectCodec mockCodec;

    @Before
    public void setUp() {
        mockCodec = mock(ObjectMapper.class);
        tokenBuffer = new TokenBuffer(mockCodec);
    }

    @Test
    public void testWriteNumberShort_positiveValue() throws IOException {
        short value = 123;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value, parser.getShortValue());
        assertEquals(value, parser.getNumberValue().shortValue());
        assertEquals(JsonToken.VALUE_NUMBER_INT, tokenBuffer.firstToken());
        assertEquals(value, ((Short)tokenBuffer.asParser().nextNumberValue()).shortValue());
    }

    @Test
    public void testWriteNumberShort_negativeValue() throws IOException {
        short value = -456;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value, parser.getShortValue());
        assertEquals(value, parser.getNumberValue().shortValue());
    }

    @Test
    public void testWriteNumberShort_zeroValue() throws IOException {
        short value = 0;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value, parser.getShortValue());
        assertEquals(value, parser.getNumberValue().shortValue());
    }

    @Test
    public void testWriteNumberShort_minShortValue() throws IOException {
        short value = Short.MIN_VALUE;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value, parser.getShortValue());
        assertEquals(value, parser.getNumberValue().shortValue());
    }

    @Test
    public void testWriteNumberShort_maxShortValue() throws IOException {
        short value = Short.MAX_VALUE;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value, parser.getShortValue());
        assertEquals(value, parser.getNumberValue().shortValue());
    }

    @Test
    public void testWriteNumberShort_multipleWrites() throws IOException {
        short value1 = 1;
        short value2 = 2;
        short value3 = 3;

        tokenBuffer.writeNumber(value1);
        tokenBuffer.writeNumber(value2);
        tokenBuffer.writeNumber(value3);

        JsonParser parser = tokenBuffer.asParser();
        assertNotNull(parser);

        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value1, parser.getShortValue());

        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value2, parser.getShortValue());

        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value3, parser.getShortValue());

        assertNull(parser.nextToken());
    }

    @Test
    public void testWriteNumberShort_afterOtherTokens() throws IOException {
        tokenBuffer.writeStartObject();
        tokenBuffer.writeFieldName("test");
        tokenBuffer.writeString("hello");
        tokenBuffer.writeNumber((short) 50);
        tokenBuffer.writeEndObject();

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("test", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("hello", parser.getText());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals((short) 50, parser.getShortValue());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }

    @Test
    public void testWriteNumberShort_withNativeIdsEnabled() throws IOException {
        tokenBuffer = new TokenBuffer(mockCodec, true);
        tokenBuffer.writeObjectId("objId");
        tokenBuffer.writeTypeId("typeId");
        short value = 100;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser();
        parser.nextToken(); // Advance to the number token
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.getCurrentToken());
        assertEquals("objId", parser.getObjectId());
        assertEquals("typeId", parser.getTypeId());
        assertEquals(value, parser.getShortValue());
    }
}
