    @Test
    public void testWriteNumberBigIntegerPositive() throws IOException {
        BigInteger positiveValue = new BigInteger("12345678901234567890");
        tokenBuffer.writeNumber(positiveValue);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(positiveValue, parser.getBigIntegerValue());
        assertEquals(positiveValue.toString(), parser.getText());
        assertEquals(JsonParser.NumberType.BIG_INTEGER, parser.getNumberType());
        parser.close();
    }

    @Test
    public void testWriteNumberBigIntegerNegative() throws IOException {
        BigInteger negativeValue = new BigInteger("-98765432109876543210");
        tokenBuffer.writeNumber(negativeValue);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(negativeValue, parser.getBigIntegerValue());
        assertEquals(negativeValue.toString(), parser.getText());
        assertEquals(JsonParser.NumberType.BIG_INTEGER, parser.getNumberType());
        parser.close();
    }

    @Test
    public void testWriteNumberBigIntegerZero() throws IOException {
        BigInteger zeroValue = BigInteger.ZERO;
        tokenBuffer.writeNumber(zeroValue);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(zeroValue, parser.getBigIntegerValue());
        assertEquals(zeroValue.toString(), parser.getText());
        assertEquals(JsonParser.NumberType.BIG_INTEGER, parser.getNumberType());
        parser.close();
    }

    @Test
    public void testWriteNumberBigIntegerNull() throws IOException {
        tokenBuffer.writeNumber((BigInteger) null);

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.VALUE_NULL, parser.nextToken());
        assertNull(parser.getText());
        parser.close();
    }

