        BigInteger value1 = new BigInteger("1");
        BigInteger value2 = new BigInteger("1000");
        BigInteger value3 = new BigInteger("-50");

        tokenBuffer.writeNumber(value1);
        tokenBuffer.writeNumber(value2);
        tokenBuffer.writeNumber(value3);
        tokenBuffer.writeNumber((BigInteger) null);

        JsonParser parser = tokenBuffer.asParser();

        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value1, parser.getBigIntegerValue());

        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value2, parser.getBigIntegerValue());

        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(value3, parser.getBigIntegerValue());

        assertEquals(JsonToken.VALUE_NULL, parser.nextToken());

        assertNull(parser.nextToken()); // End of buffer
        parser.close();
    }

