        // Initialize TokenBuffer with a mock ObjectCodec
        ObjectCodec mockCodec = Mockito.mock(ObjectCodec.class);
        tokenBuffer = new TokenBuffer(mockCodec);

        // Mock the _last segment and _appendAt for controlled testing
        mockSegment = Mockito.mock(Segment.class);
        setInternalState(tokenBuffer, "_last", mockSegment);
        setInternalState(tokenBuffer, "_first", mockSegment); // Ensure _first points to _last initially
        setInternalState(tokenBuffer, "_appendAt", 0);
        setInternalState(tokenBuffer, "_closed", false); // Ensure not closed

        // Mock Segment.append to return null (meaning segment not full) or a new segment
        when(mockSegment.append(anyInt(), any(JsonToken.class), any(Object.class))).thenReturn(null);
        when(mockSegment.append(anyInt(), any(JsonToken.class), any(Object.class), any(), any())).thenReturn(null);

        // Mock the static TOKEN_TYPES_BY_INDEX for Segment
        setupSegmentTokenTypesByIndex();
    }

    // Helper to set private fields using reflection
    private void setInternalState(Object target, String fieldName, Object value) throws NoSuchFieldException, IllegalAccessException {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    // Helper to get private fields using reflection
    private Object getInternalState(Object target, String fieldName) throws NoSuchFieldException, IllegalAccessException {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(target);
    }

    private void setupSegmentTokenTypesByIndex() throws NoSuchFieldException, IllegalAccessException {
        // Access the private static final TOKEN_TYPES_BY_INDEX field in Segment
        Field field = Segment.class.getDeclaredField("TOKEN_TYPES_BY_INDEX");
        field.setAccessible(true);
        JsonToken[] tokenTypesByIndex = (JsonToken[]) field.get(null);

        // Ensure it's not null and initialize if necessary (minimal for this test)
        if (tokenTypesByIndex == null || tokenTypesByIndex.length < JsonToken.VALUE_NUMBER_INT.ordinal()) {
            JsonToken[] newTokenTypes = new JsonToken[32]; // Arbitrary larger size
            System.arraycopy(tokenTypesByIndex, 0, newTokenTypes, 0, tokenTypesByIndex.length);
            field.set(null, newTokenTypes);
            tokenTypesByIndex = newTokenTypes;
        }

        // Populate required token types
        for (JsonToken t : JsonToken.values()) {
            if (t.ordinal() < tokenTypesByIndex.length) {
                tokenTypesByIndex[t.ordinal()] = t;
            }
        }
    }


