    @Test
    public void testConstructWithSuperClassResolution() {
        // This test indirectly checks the delegation to the internal construct method
        // which sets up default bindings and superclass based on the rawType.
        Class<?> rawType = HashMap.class;
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = typeFactory.constructType(Integer.class);

        MapType mapType = MapType.construct(rawType, keyType, valueType);

        assertNotNull(mapType.getSuperClass());
        // For HashMap, its immediate superclass is AbstractMap
        assertEquals(java.util.AbstractMap.class, mapType.getSuperClass().getRawClass());

        // Also check interfaces
        assertNotNull(mapType.getSuperInterfaces());
        boolean foundMapInterface = false;
        for (JavaType superInt : mapType.getSuperInterfaces()) {
            if (superInt.getRawClass().equals(Map.class)) {
                foundMapInterface = true;
                break;
            }
        }
        assertTrue(foundMapInterface);
    }
