import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Tag;
import org.jsoup.select.Elements;
import org.junit.Test;

import static org.junit.Assert.*;

public class ElementSiblingElementsTest {

    @Test
    public void testSiblingElementsWithNoParent() {
        Element element = new Element(Tag.valueOf("div"), "");
        Elements siblings = element.siblingElements();
        assertNotNull(siblings);
        assertTrue(siblings.isEmpty());
    }

    @Test
    public void testSiblingElementsWithOneSibling() {
        Document doc = new Document("");
        Element parent = doc.appendElement("parent");
        Element child1 = parent.appendElement("child1");
        Element child2 = parent.appendElement("child2");

        Elements siblingsOfChild1 = child1.siblingElements();
        assertNotNull(siblingsOfChild1);
        assertEquals(2, siblingsOfChild1.size());
        assertTrue(siblingsOfChild1.contains(child1));
        assertTrue(siblingsOfChild1.contains(child2));

        Elements siblingsOfChild2 = child2.siblingElements();
        assertNotNull(siblingsOfChild2);
        assertEquals(2, siblingsOfChild2.size());
        assertTrue(siblingsOfChild2.contains(child1));
        assertTrue(siblingsOfChild2.contains(child2));
    }

    @Test
    public void testSiblingElementsWithMultipleSiblings() {
        Document doc = new Document("");
        Element parent = doc.appendElement("parent");
        Element child1 = parent.appendElement("child1");
        Element child2 = parent.appendElement("child2");
        Element child3 = parent.appendElement("child3");
        Element child4 = parent.appendElement("child4");

        Elements siblingsOfChild2 = child2.siblingElements();
        assertNotNull(siblingsOfChild2);
        assertEquals(4, siblingsOfChild2.size());
        assertTrue(siblingsOfChild2.contains(child1));
        assertTrue(siblingsOfChild2.contains(child2));
        assertTrue(siblingsOfChild2.contains(child3));
        assertTrue(siblingsOfChild2.contains(child4));

        Elements siblingsOfChild4 = child4.siblingElements();
        assertNotNull(siblingsOfChild4);
        assertEquals(4, siblingsOfChild4.size());
        assertTrue(siblingsOfChild4.contains(child1));
        assertTrue(siblingsOfChild4.contains(child2));
        assertTrue(siblingsOfChild4.contains(child3));
        assertTrue(siblingsOfChild4.contains(child4));
    }

    @Test
    public void testSiblingElementsWithOnlyItself() {
        Document doc = new Document("");
        Element parent = doc.appendElement("parent");
        Element child = parent.appendElement("child");

        Elements siblings = child.siblingElements();
        assertNotNull(siblings);
        assertEquals(1, siblings.size());
        assertTrue(siblings.contains(child));
    }

    @Test
    public void testSiblingElementsFromDetachedElement() {
        Element element = new Element(Tag.valueOf("span"), "");
        Elements siblings = element.siblingElements();
        assertNotNull(siblings);
        assertTrue(siblings.isEmpty());
    }

    @Test
    public void testSiblingElementsFromRootElement() {
        Document doc = new Document("");
        Element html = doc.appendElement("html");
        Element head = html.appendElement("head");
        Element body = html.appendElement("body");

        Elements siblingsOfHtml = html.siblingElements();
        assertNotNull(siblingsOfHtml);
        assertTrue(siblingsOfHtml.isEmpty()); // Root element has no parent, thus no siblings

        Elements siblingsOfHead = head.siblingElements();
        assertNotNull(siblingsOfHead);
        assertEquals(2, siblingsOfHead.size());
        assertTrue(siblingsOfHead.contains(head));
        assertTrue(siblingsOfHead.contains(body));
    }

    @Test
    public void testSiblingElementsWhenParentHasNoOtherElements() {
        Document doc = new Document("");
        Element parent = doc.appendElement("parent");
        Element child = parent.appendElement("child");

        Elements siblings = child.siblingElements();
        assertNotNull(siblings);
        assertEquals(1, siblings.size());
        assertTrue(siblings.contains(child));
    }

    @Test
    public void testSiblingElementsOrder() {
        Document doc = new Document("");
        Element parent = doc.appendElement("parent");
        Element child1 = parent.appendElement("child1");
        Element child2 = parent.appendElement("child2");
        Element child3 = parent.appendElement("child3");

        Elements siblings = child1.siblingElements();
        assertNotNull(siblings);
        assertEquals(3, siblings.size());
        assertEquals(child1, siblings.get(0));
        assertEquals(child2, siblings.get(1));
        assertEquals(child3, siblings.get(2));
    }

    @Test
    public void testSiblingElementsAfterRemovingASibling() {
        Document doc = new Document("");
        Element parent = doc.appendElement("parent");
        Element child1 = parent.appendElement("child1");
        Element child2 = parent.appendElement("child2");
        Element child3 = parent.appendElement("child3");

        child2.remove();

        Elements siblingsOfChild1 = child1.siblingElements();
        assertNotNull(siblingsOfChild1);
        assertEquals(2, siblingsOfChild1.size());
        assertTrue(siblingsOfChild1.contains(child1));
        assertFalse(siblingsOfChild1.contains(child2));
        assertTrue(siblingsOfChild1.contains(child3));
    }
}
