import org.jsoup.nodes.Document;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.Attributes;
import org.junit.Before;
import org.junit.Test;

import java.util.List;
import java.util.ArrayList;

import static org.junit.Assert.*;

public class NodeSiblingNodesTest {

    private Document parentDocument;
    private Node node1, node2, node3, node4;

    @Before
    public void setUp() {
        parentDocument = new Document("");
        node1 = new Node("") {};
        node2 = new Node("") {};
        node3 = new Node("") {};
        node4 = new Node("") {};

        // Add to parentDocument's childNodes for testing parent-child relationships
        // This is a workaround as Node's constructors don't directly establish parent-child links easily.
        // We will simulate parent-child relationships for testing.
    }

    // Custom helper to simulate adding children to a parent and setting parent/siblingIndex
    private void addChildNodes(Node parent, Node... children) {
        if (parent.childNodes == null) {
            parent.childNodes = new ArrayList<>();
        }
        for (int i = 0; i < children.length; i++) {
            Node child = children[i];
            parent.childNodes.add(child);
            child.parentNode = parent;
            child.siblingIndex = i;
        }
    }

    @Test
    public void testSiblingNodesWithMultipleSiblings() {
        addChildNodes(parentDocument, node1, node2, node3);

        List<Node> siblingsOfNode1 = node1.siblingNodes();
        assertNotNull(siblingsOfNode1);
        assertEquals(2, siblingsOfNode1.size());
        assertTrue(siblingsOfNode1.contains(node2));
        assertTrue(siblingsOfNode1.contains(node3));
        assertFalse(siblingsOfNode1.contains(node1)); // Should not contain itself

        List<Node> siblingsOfNode2 = node2.siblingNodes();
        assertNotNull(siblingsOfNode2);
        assertEquals(2, siblingsOfNode2.size());
        assertTrue(siblingsOfNode2.contains(node1));
        assertTrue(siblingsOfNode2.contains(node3));
        assertFalse(siblingsOfNode2.contains(node2));

        List<Node> siblingsOfNode3 = node3.siblingNodes();
        assertNotNull(siblingsOfNode3);
        assertEquals(2, siblingsOfNode3.size());
        assertTrue(siblingsOfNode3.contains(node1));
        assertTrue(siblingsOfNode3.contains(node2));
        assertFalse(siblingsOfNode3.contains(node3));
    }

    @Test
    public void testSiblingNodesWithNoParent() {
        // node1 has no parent by default in setUp()
        List<Node> siblings = node1.siblingNodes();
        assertNotNull(siblings);
        assertTrue(siblings.isEmpty());
    }

    @Test
    public void testSiblingNodesWithOnlyOneChild() {
        addChildNodes(parentDocument, node1);

        List<Node> siblings = node1.siblingNodes();
        assertNotNull(siblings);
        assertTrue(siblings.isEmpty());
    }

    @Test
    public void testSiblingNodesWhenParentHasNoChildren() {
        // Here, parentDocument is a node, but we haven't added any children to it.
        // So, if we somehow set node1's parent to parentDocument but parentDocument.childNodes is null or empty,
        // it should return an empty list.
        node1.parentNode = parentDocument; // Manually set parent
        node1.siblingIndex = 0; // Manually set sibling index (even though there are no siblings)

        // Simulate parent having no children array or an empty one
        parentDocument.childNodes = null;
        List<Node> siblings = node1.siblingNodes();
        assertNotNull(siblings);
        assertTrue(siblings.isEmpty());

        parentDocument.childNodes = new ArrayList<>();
        siblings = node1.siblingNodes();
        assertNotNull(siblings);
        assertTrue(siblings.isEmpty());
    }


    @Test
    public void testSiblingNodesReturnedListIsNewCollection() {
        addChildNodes(parentDocument, node1, node2, node3);

        List<Node> siblings = node1.siblingNodes();
        assertEquals(2, siblings.size());

        siblings.add(node4); // Modify the returned list

        // Ensure the original DOM structure (parent's children) is not affected
        assertEquals(3, parentDocument.childNodes().size());
        assertTrue(parentDocument.childNodes().contains(node1));
        assertTrue(parentDocument.childNodes().contains(node2));
        assertTrue(parentDocument.childNodes().contains(node3));
        assertFalse(parentDocument.childNodes().contains(node4)); // node4 should not be added to parent
    }

    @Test
    public void testSiblingNodesWithMoreChildren() {
        addChildNodes(parentDocument, node1, node2, node3, node4);

        List<Node> siblingsOfNode2 = node2.siblingNodes();
        assertNotNull(siblingsOfNode2);
        assertEquals(3, siblingsOfNode2.size());
        assertTrue(siblingsOfNode2.contains(node1));
        assertTrue(siblingsOfNode2.contains(node3));
        assertTrue(siblingsOfNode2.contains(node4));
        assertFalse(siblingsOfNode2.contains(node2));
    }

    @Test
    public void testSiblingNodesWithSelfAsOnlyChild() {
        addChildNodes(parentDocument, node1);
        List<Node> siblings = node1.siblingNodes();
        assertNotNull(siblings);
        assertTrue(siblings.isEmpty());
    }

    @Test
    public void testSiblingNodesWithNullParentNode() {
        Node orphanNode = new Node("") {}; // No parent
        List<Node> siblings = orphanNode.siblingNodes();
        assertNotNull(siblings);
        assertTrue(siblings.isEmpty());
    }

    @Test
    public void testSiblingNodesWithDifferentNodeImplementations() {
        class CustomNodeA extends Node {
            public CustomNodeA() { super(""); }
        }
        class CustomNodeB extends Node {
            public CustomNodeB() { super(""); }
        }

        CustomNodeA customNodeA = new CustomNodeA();
        CustomNodeB customNodeB = new CustomNodeB();
        Node regularNode = new Node("") {};

        Document customParent = new Document("");
        addChildNodes(customParent, customNodeA, customNodeB, regularNode);

        List<Node> siblingsOfCustomNodeA = customNodeA.siblingNodes();
        assertEquals(2, siblingsOfCustomNodeA.size());
        assertTrue(siblingsOfCustomNodeA.contains(customNodeB));
        assertTrue(siblingsOfCustomNodeA.contains(regularNode));
    }
}
