    public void testPreviousSiblingWhenHasPreviousSibling() {
        // Node has a previous sibling
        parent.addChildren(child1, child2, child3);
        assertEquals(child1, child2.previousSibling());
        assertEquals(child2, child3.previousSibling());
    }

    @Test
    public void testPreviousSiblingWhenOnlyChild() {
        // Node is the only child
        parent.addChildren(child1);
        assertNull(child1.previousSibling());
    }

    @Test
    public void testPreviousSiblingWithEmptyParentChildrenList() {
        // Although childNodes is usually managed internally by addChildren,
        // we can simulate a scenario where a parent has no children
        // but a node somehow thinks it's part of it (shouldn't happen in real use)
        // This test ensures robustness if internal state is inconsistent
        Node orphanNode = new Node("http://example.com") {};
        // Manually set parent, but without adding to parent's children list
        orphanNode.parentNode = parent;
        assertNull(orphanNode.previousSibling());
    }
}
