import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Whitelist;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;

public class CleanerCleanTest {

    private Cleaner cleaner;
    private Whitelist whitelist;

    @Before
    public void setUp() {
        whitelist = Whitelist.basic();
        cleaner = new Cleaner(whitelist);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testClean_DirtyDocumentIsNull() {
        cleaner.clean(null);
    }

    @Test
    public void testClean_EmptyDocument() {
        Document dirtyDocument = Jsoup.parse("");
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals(dirtyDocument.baseUri(), cleanDocument.baseUri());
        assertTrue(cleanDocument.body().children().isEmpty());
    }

    @Test
    public void testClean_BasicAllowedTagsAndAttributes() {
        String html = "<html><head><title>Test</title></head><body><p><a href=\"http://example.com\">Link</a></p></body></html>";
        Document dirtyDocument = Jsoup.parse(html, "http://example.org");
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("http://example.org", cleanDocument.baseUri());

        Element body = cleanDocument.body();
        assertNotNull(body);
        assertEquals(1, body.children().size());

        Element p = body.children().first();
        assertEquals("p", p.tagName());
        assertEquals(1, p.children().size());

        Element a = p.children().first();
        assertEquals("a", a.tagName());
        assertEquals("Link", a.text());
        assertEquals("http://example.com", a.attr("href"));
    }

    @Test
    public void testClean_DisallowedTag() {
        String html = "<html><body><script>alert('xss');</script><p>Safe content</p></body></html>";
        Document dirtyDocument = Jsoup.parse(html);
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        Element body = cleanDocument.body();
        assertNotNull(body);
        assertEquals(1, body.children().size());
        assertEquals("p", body.children().first().tagName());
        assertEquals("Safe content", body.children().first().text());
    }

    @Test
    public void testClean_DisallowedAttribute() {
        String html = "<html><body><p style=\"color:red;\">Safe content</p></body></html>";
        Document dirtyDocument = Jsoup.parse(html);
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        Element p = cleanDocument.body().children().first();
        assertNotNull(p);
        assertEquals("p", p.tagName());
        assertFalse(p.hasAttr("style"));
        assertEquals("Safe content", p.text());
    }

    @Test
