        assertEquals(2, ul.children().size());
        assertEquals("li", ul.children().first().tagName());
        assertEquals("List item 1", ul.children().first().text());
        assertEquals("li", ul.children().get(1).tagName());
        assertEquals("List item 2", ul.children().get(1).text());
    }

    @Test
