        assertEquals("a", mailLink.tagName());
        assertEquals("mailto:test@example.com", mailLink.attr("href"));

        Element phoneLink = body.children().get(1);
        assertEquals("a", phoneLink.tagName());
        assertEquals("tel:+1234567890", phoneLink.attr("href"));
    }
