        assertEquals("My Document Title", doc.title());
    }

    @Test
    public void testTitleWithMultipleTitleElements() {
        Document doc = new Document("http://example.com");
        doc.appendElement("head").appendElement("title").text("First Title");
        doc.head().appendElement("title").text("Second Title"); // Only the first one should be considered
        assertEquals("First Title", doc.title());
    }

    @Test
    public void testTitleWithNoTitleElement() {
        Document doc = new Document("http://example.com");
        doc.appendElement("body").appendElement("p").text("Some content");
        assertEquals("", doc.title());
    }

    @Test
    public void testTitleWithEmptyTitleElement() {
        Document doc = new Document("http://example.com");
        doc.appendElement("head").appendElement("title").text("");
        assertEquals("", doc.title());
    }

    @Test
    public void testTitleWithWhitespaceInTitleElement() {
        Document doc = new Document("http://example.com");
        doc.appendElement("head").appendElement("title").text("  My Title With Whitespace  ");
        assertEquals("My Title With Whitespace", doc.title());
    }

