    @Test
    public void testTitleWhenTitleElementIsNotInHead() {
        // According to the Jsoup behavior, a <title> element outside of <head>
        // is generally not considered the document's title.
        // The implementation specifically looks for the first <title> element
        // regardless of its parent, but in a well-formed HTML, it should be in head.
        // Let's test this edge case.
        Document doc = new Document("http://example.com");
        doc.appendElement("body").appendElement("title").text("Title in Body");
        assertEquals("Title in Body", doc.title()); // Jsoup's current implementation finds it.
    }

    @Test
    public void testTitleWithNoHeadElementButTitlePresent() {
        Document doc = new Document("http://example.com");
        doc.appendElement("html").appendElement("title").text("Title without Head");
        assertEquals("Title without Head", doc.title());
    }

    @Test
    public void testTitleAfterModifyingTitleThroughSetter() {
        Document doc = new Document("http://example.com");
        doc.title("Initial Title");
        assertEquals("Initial Title", doc.title());

        doc.title("Updated Title");
        assertEquals("Updated Title", doc.title());
    }

