        doc.appendElement("head").appendElement("title").text("Old Title");
        assertEquals("Old Title", doc.title());

        doc.title("Brand New Title");
        assertEquals("Brand New Title", doc.title());
        // Verify only one title element exists now
        assertEquals(1, doc.head().select("title").size());
