import org.apache.commons.math.util.MultidimensionalCounter;
import org.apache.commons.math.util.MultidimensionalCounter.OutOfRangeException;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;

public class MultidimensionalCounterGetCountsTest {

    private MultidimensionalCounter counter2x3x4;
    private MultidimensionalCounter counter1x1x1;
    private MultidimensionalCounter counter5;

    @Before
    public void setUp() {
        counter2x3x4 = new MultidimensionalCounter(2, 3, 4);
        counter1x1x1 = new MultidimensionalCounter(1, 1, 1);
        counter5 = new MultidimensionalCounter(5);
    }

    @Test
    public void testGetCounts_ZeroIndex() {
        assertArrayEquals(new int[]{0, 0, 0}, counter2x3x4.getCounts(0));
        assertArrayEquals(new int[]{0}, counter5.getCounts(0));
        assertArrayEquals(new int[]{0, 0, 0}, counter1x1x1.getCounts(0));
    }

    @Test
    public void testGetCounts_MidIndex() {
        assertArrayEquals(new int[]{1, 0, 1}, counter2x3x4.getCounts(13)); // Example from docstring
        assertArrayEquals(new int[]{0, 1, 0}, counter2x3x4.getCounts(4)); // (0*3*4) + (1*4) + 0 = 4
        assertArrayEquals(new int[]{2}, counter5.getCounts(2));
    }

    @Test
    public void testGetCounts_MaxIndex() {
        assertArrayEquals(new int[]{1, 2, 3}, counter2x3x4.getCounts(23)); // Total size is 2*3*4 = 24, max index is 23
        assertArrayEquals(new int[]{4}, counter5.getCounts(4));
        assertArrayEquals(new int[]{0, 0, 0}, counter1x1x1.getCounts(0)); // Max index is 0
    }

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_NegativeIndex() {
        counter2x3x4.getCounts(-1);
    }

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_IndexTooLarge() {
        counter2x3x4.getCounts(24); // Total size is 24
    }

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_IndexTooLargeForSingleDimension() {
        counter5.getCounts(5); // Total size is 5
    }

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_IndexTooLargeFor1x1x1() {
        counter1x1x1.getCounts(1); // Total size is 1
    }

    @Test
    public void testGetCounts_ComplexScenario() {
        MultidimensionalCounter counter3x5x2 = new MultidimensionalCounter(3, 5, 2);
        // linear index = c0*stride0 + c1*stride1 + c2*stride2
        // strides: (5*2)=10, (2)=2, 1
        // (1, 2, 1) -> 1*10 + 2*2 + 1*1 = 10 + 4 + 1 = 15
        assertArrayEquals(new int[]{1, 2, 1}, counter3x5x2.getCounts(15));

        // (2, 4, 0) -> 2*10 + 4*2 + 0*1 = 20 + 8 + 0 = 28
        assertArrayEquals(new int[]{2, 4, 0}, counter3x5x2.getCounts(28));
    }

    @Test
    public void testGetCounts_SingleDimension() {
        MultidimensionalCounter counter10 = new MultidimensionalCounter(10);
        assertArrayEquals(new int[]{0}, counter10.getCounts(0));
        assertArrayEquals(new int[]{5}, counter10.getCounts(5));
        assertArrayEquals(new int[]{9}, counter10.getCounts(9));
    }
}
