import org.junit.Test;
import static org.junit.Assert.*;
import org.apache.commons.math.util.FastMath;

public class FastMathMaxFloatTest {

    @Test
    public void testMaxPositiveNumbers() {
        assertEquals(5.0f, FastMath.max(2.0f, 5.0f), 0.0f);
        assertEquals(10.5f, FastMath.max(10.5f, 3.2f), 0.0f);
        assertEquals(7.0f, FastMath.max(7.0f, 7.0f), 0.0f);
    }

    @Test
    public void testMaxNegativeNumbers() {
        assertEquals(-2.0f, FastMath.max(-5.0f, -2.0f), 0.0f);
        assertEquals(-1.0f, FastMath.max(-10.0f, -1.0f), 0.0f);
        assertEquals(-3.0f, FastMath.max(-3.0f, -3.0f), 0.0f);
    }

    @Test
    public void testMaxMixedSigns() {
        assertEquals(5.0f, FastMath.max(-2.0f, 5.0f), 0.0f);
        assertEquals(10.5f, FastMath.max(10.5f, -3.2f), 0.0f);
        assertEquals(0.0f, FastMath.max(-7.0f, 0.0f), 0.0f);
    }

    @Test
    public void testMaxZeroValues() {
        assertEquals(0.0f, FastMath.max(0.0f, -5.0f), 0.0f);
        assertEquals(0.0f, FastMath.max(-0.0f, 0.0f), 0.0f);
        assertEquals(0.0f, FastMath.max(0.0f, 0.0f), 0.0f);
        assertEquals(0.0f, FastMath.max(-0.0f, -0.0f), 0.0f);
        assertEquals(0.0f, FastMath.max(0.0f, 5.0f), 0.0f); // Positive zero is greater than negative number
    }

    @Test
    public void testMaxNaNValues() {
        // If either argument is Float.NaN, the result is the other argument.
        assertTrue(Float.isNaN(FastMath.max(Float.NaN, Float.NaN)));
        assertEquals(5.0f, FastMath.max(Float.NaN, 5.0f), 0.0f);
        assertEquals(5.0f, FastMath.max(5.0f, Float.NaN), 0.0f);
        assertEquals(-10.0f, FastMath.max(Float.NaN, -10.0f), 0.0f);
        assertEquals(-10.0f, FastMath.max(-10.0f, Float.NaN), 0.0f);
        assertEquals(0.0f, FastMath.max(Float.NaN, 0.0f), 0.0f);
    }

    @Test
    public void testMaxInfinityValues() {
        assertEquals(Float.POSITIVE_INFINITY, FastMath.max(Float.POSITIVE_INFINITY, 5.0f), 0.0f);
        assertEquals(Float.POSITIVE_INFINITY, FastMath.max(5.0f, Float.POSITIVE_INFINITY), 0.0f);
        assertEquals(Float.POSITIVE_INFINITY, FastMath.max(Float.POSITIVE_INFINITY, Float.POSITIVE_INFINITY), 0.0f);
        assertEquals(5.0f, FastMath.max(Float.NEGATIVE_INFINITY, 5.0f), 0.0f);
        assertEquals(5.0f, FastMath.max(5.0f, Float.NEGATIVE_INFINITY), 0.0f);
        assertEquals(Float.NEGATIVE_INFINITY, FastMath.max(Float.NEGATIVE_INFINITY, Float.NEGATIVE_INFINITY), 0.0f);
        assertEquals(Float.POSITIVE_INFINITY, FastMath.max(Float.NEGATIVE_INFINITY, Float.POSITIVE_INFINITY), 0.0f);
        assertEquals(Float.POSITIVE_INFINITY, FastMath.max(Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY), 0.0f);
    }

    @Test
    public void testMaxMinMaxFloatValues() {
        assertEquals(Float.MAX_VALUE, FastMath.max(Float.MIN_VALUE, Float.MAX_VALUE), 0.0f);
        assertEquals(Float.MAX_VALUE, FastMath.max(Float.MAX_VALUE, Float.MIN_VALUE), 0.0f);
        assertEquals(Float.MAX_VALUE, FastMath.max(Float.MAX_VALUE, Float.MAX_VALUE), 0.0f);
        assertEquals(Float.MIN_VALUE, FastMath.max(Float.MIN_VALUE, Float.MIN_VALUE), 0.0f);
    }

    @Test
    public void testMaxSubnormalNumbers() {
