        assertTrue(Arrays.asList("A", "B", "C").contains(result[0]));
    }

    @Test
    public void testSample_multipleElements() throws NotStrictlyPositiveException, MathIllegalArgumentException, IllegalStateException {
        int sampleSize = 100;
        String[] result = distribution.sample(sampleSize);
        assertNotNull(result);
        assertEquals(sampleSize, result.length);
        for (String s : result) {
            assertTrue(Arrays.asList("A", "B", "C").contains(s));
        }
    }

