        List<Pair<String, Double>> emptySamples = new ArrayList<>();
        DiscreteDistribution<String> emptyDistribution = new DiscreteDistribution<>(emptySamples);
        emptyDistribution.sample(1);
    }

    @Test
    public void testSample_distributionWithOneElement() throws NotStrictlyPositiveException, MathIllegalArgumentException, IllegalStateException, NotPositiveException, MathArithmeticException {
        List<Pair<String, Double>> singleSample = new ArrayList<>();
        singleSample.add(new Pair<>("X", 1.0));
        DiscreteDistribution<String> singleElementDistribution = new DiscreteDistribution<>(singleSample);
        String[] result = singleElementDistribution.sample(5);
        assertNotNull(result);
        assertEquals(5, result.length);
        for (String s : result) {
