    @Test
    public void testFromCalendarFields_ValidCalendar() {
        // Test with a typical Calendar instance
        Calendar calendar = new GregorianCalendar(2023, Calendar.JANUARY, 15, 10, 30, 45);
        calendar.set(Calendar.MILLISECOND, 123);

        LocalDateTime localDateTime = LocalDateTime.fromCalendarFields(calendar);

        assertNotNull(localDateTime);
        assertEquals(2023, localDateTime.getYear());
        assertEquals(1, localDateTime.getMonthOfYear()); // Joda-Time months are 1-based
        assertEquals(15, localDateTime.getDayOfMonth());
        assertEquals(10, localDateTime.getHourOfDay());
        assertEquals(30, localDateTime.getMinuteOfHour());
        assertEquals(45, localDateTime.getSecondOfMinute());
        assertEquals(123, localDateTime.getMillisOfSecond());
    }

    @Test
    public void testFromCalendarFields_NullCalendar() {
        // Test with a null Calendar instance, expecting an IllegalArgumentException
        try {
            LocalDateTime.fromCalendarFields(null);
            fail("Expected IllegalArgumentException for null calendar");
        } catch (IllegalArgumentException e) {
            assertEquals("The calendar must not be null", e.getMessage());
        }
    }

