        // fromCalendarFields should ignore the time zone and just extract the fields.
        TimeZone estTimeZone = TimeZone.getTimeZone("America/New_York");
        Calendar calendar = new GregorianCalendar(estTimeZone);
        calendar.set(2024, Calendar.FEBRUARY, 29, 23, 59, 59);
        calendar.set(Calendar.MILLISECOND, 999);

        LocalDateTime localDateTime = LocalDateTime.fromCalendarFields(calendar);

        assertNotNull(localDateTime);
        assertEquals(2024, localDateTime.getYear());
        assertEquals(2, localDateTime.getMonthOfYear());
        assertEquals(29, localDateTime.getDayOfMonth());
        assertEquals(23, localDateTime.getHourOfDay());
        assertEquals(59, localDateTime.getMinuteOfHour());
        assertEquals(59, localDateTime.getSecondOfMinute());
        assertEquals(999, localDateTime.getMillisOfSecond());
    }

    @Test
