import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeConstants;
import org.joda.time.DateTimeZone;
import org.joda.time.LocalDateTime;
import org.junit.Test;
import static org.junit.Assert.*;

import java.util.Date;
import java.util.Calendar;
import java.util.GregorianCalendar;

public class LocalDateTimeFromDateFieldsTest {

    // Test case 1: Happy path - basic conversion of a Date object
    @Test
    public void testFromDateFields_basicConversion() {
        // Create a Date object representing a specific moment in time
        Calendar calendar = new GregorianCalendar(2023, Calendar.MARCH, 15, 10, 30, 45);
        calendar.set(Calendar.MILLISECOND, 123);
        Date date = calendar.getTime();

        // Convert to LocalDateTime using the method under test
        LocalDateTime localDateTime = LocalDateTime.fromDateFields(date);

        // Assert that the LocalDateTime components match the Date components in the default time zone
        assertEquals(2023, localDateTime.getYear());
        assertEquals(DateTimeConstants.MARCH, localDateTime.getMonthOfYear());
        assertEquals(15, localDateTime.getDayOfMonth());
        assertEquals(10, localDateTime.getHourOfDay());
        assertEquals(30, localDateTime.getMinuteOfHour());
        assertEquals(45, localDateTime.getSecondOfMinute());
        assertEquals(123, localDateTime.getMillisOfSecond());
    }

    // Test case 2: Test with a Date object at the epoch (January 1, 1970, 00:00:00 UTC)
    @Test
    public void testFromDateFields_epochDate() {
        Date date = new Date(0); // Epoch
        LocalDateTime localDateTime = LocalDateTime.fromDateFields(date);

        // Assuming default time zone is GMT+0, adjust if running in a different timezone
        // For example, if default timezone is EST (GMT-5), it would be 1969 Dec 31 19:00:00
        // To make it robust, we compare with a LocalDateTime created from the same epoch in the default zone
        DateTime dateTimeInDefaultZone = new DateTime(0L, DateTimeZone.getDefault());
        LocalDateTime expectedLocalDateTime = dateTimeInDefaultZone.toLocalDateTime();

        assertEquals(expectedLocalDateTime, localDateTime);
    }

    // Test case 3: Test with a Date object representing the maximum possible date
    // Note: java.util.Date has limitations on its range. This uses a date far in the future.
    @Test
    public void testFromDateFields_futureDate() {
        Calendar calendar = new GregorianCalendar(2050, Calendar.DECEMBER, 31, 23, 59, 59);
        calendar.set(Calendar.MILLISECOND, 999);
        Date date = calendar.getTime();

        LocalDateTime localDateTime = LocalDateTime.fromDateFields(date);

        assertEquals(2050, localDateTime.getYear());
        assertEquals(DateTimeConstants.DECEMBER, localDateTime.getMonthOfYear());
        assertEquals(31, localDateTime.getDayOfMonth());
        assertEquals(23, localDateTime.getHourOfDay());
        assertEquals(59, localDateTime.getMinuteOfHour());
        assertEquals(59, localDateTime.getSecondOfMinute());
        assertEquals(999, localDateTime.getMillisOfSecond());
    }

    // Test case 4: Test with a Date object representing a past date
    @Test
    public void testFromDateFields_pastDate() {
        Calendar calendar = new GregorianCalendar(1990, Calendar.JANUARY, 1, 1, 1, 1);
        calendar.set(Calendar.MILLISECOND, 1);
        Date date = calendar.getTime();

        LocalDateTime localDateTime = LocalDateTime.fromDateFields(date);

        assertEquals(1990, localDateTime.getYear());
        assertEquals(DateTimeConstants.JANUARY, localDateTime.getMonthOfYear());
        assertEquals(1, localDateTime.getDayOfMonth());
        assertEquals(1, localDateTime.getHourOfDay());
        assertEquals(1, localDateTime.getMinuteOfHour());
        assertEquals(1, localDateTime.getSecondOfMinute());
        assertEquals(1, localDateTime.getMillisOfSecond());
    }

    // Test case 5: Test with a Date object with zero milliseconds
    @Test
    public void testFromDateFields_zeroMilliseconds() {
        Calendar calendar = new GregorianCalendar(2020, Calendar.FEBRUARY, 29, 12, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);
        Date date = calendar.getTime();

        LocalDateTime localDateTime = LocalDateTime.fromDateFields(date);

        assertEquals(2020, localDateTime.getYear());
        assertEquals(DateTimeConstants.FEBRUARY, localDateTime.getMonthOfYear());
        assertEquals(29, localDateTime.getDayOfMonth());
        assertEquals(12, localDateTime.getHourOfDay());
        assertEquals(0, localDateTime.getMinuteOfHour());
        assertEquals(0, localDateTime.getSecondOfMinute());
        assertEquals(0, localDateTime.getMillisOfSecond());
    }

    // Test case 6: Test with a Date object having maximum milliseconds (999)
    @Test
    public void testFromDateFields_maxMilliseconds() {
        Calendar calendar = new GregorianCalendar(2021, Calendar.APRIL, 1, 23, 59, 59);
        calendar.set(Calendar.MILLISECOND, 999);
        Date date = calendar.getTime();

        LocalDateTime localDateTime = LocalDateTime.fromDateFields(date);

        assertEquals(2021, localDateTime.getYear());
        assertEquals(DateTimeConstants.APRIL, localDateTime.getMonthOfYear());
        assertEquals(1, localDateTime.getDayOfMonth());
        assertEquals(23, localDateTime.getHourOfDay());
        assertEquals(59, localDateTime.getMinuteOfHour());
        assertEquals(59, localDateTime.getSecondOfMinute());
        assertEquals(999, localDateTime.getMillisOfSecond());
    }

    // Test case 7: Test conversion across daylight saving time transition (if applicable in default zone)
    // This test's outcome depends heavily on the default time zone where the test is run.
    // It's difficult to make a universally passing test for DST without knowing the default zone.
    // The key is that it uses the *system's default time zone*.
    @Test
    public void testFromDateFields_dstTransition() {
        // This example assumes a time zone that observes DST, e.g., "America/New_York"
        // Let's pick a date just before and just after a spring forward (e.g., March 14, 2021, 2 AM EST -> 3 AM EDT)
        // Or a fall back (e.g., Nov 7, 2021, 2 AM EDT -> 1 AM EST)

        // For simplicity and to avoid time zone specific setup, we'll confirm
        // that the conversion accurately reflects the *system's* interpretation.
        // Let's test a date that might fall into an "unrepresented" hour during spring forward,
        // or a "repeated" hour during fall back.
        // The Java Date object correctly handles these, and LocalDateTime.fromDateFields should reflect that.

        // Example: Spring forward (e.g., March 14, 2021, 2 AM EST becomes 3 AM EDT)
        // If we create a Date for 2:30 AM EST on Mar 14, 2021, the JVM will interpret it as 3:30 AM EDT.
        // LocalDateTime should reflect this.
        Calendar calendar = new GregorianCalendar(2021, Calendar.MARCH, 14, 2, 30, 0); // 2:30 AM
        Date date = calendar.getTime();

        LocalDateTime localDateTime = LocalDateTime.fromDateFields(date);

        // The exact expected hour depends on the default timezone's DST rules for that date.
        // We can get the expected hour by creating a DateTime and converting it.
        DateTime expectedDateTime = new DateTime(date.getTime(), DateTimeZone.getDefault());
        assertEquals(expectedDateTime.toLocalDateTime(), localDateTime);
    }


    // Test case 8: Null input check - should throw IllegalArgumentException
    @Test(expected = IllegalArgumentException.class)
    public void testFromDateFields_nullDate() {
        LocalDateTime.fromDateFields(null);
    }

    // Test case 9: Verify the chronology used (should be ISOChronology)
    @Test
    public void testFromDateFields_chronology() {
        Date date = new Date();
        LocalDateTime localDateTime = LocalDateTime.fromDateFields(date);
        assertNotNull(localDateTime.getChronology());
        // By default, LocalDateTime uses ISOChronology
        assertTrue(localDateTime.getChronology().toString().contains("ISOChronology"));
    }

    // Test case 10: Test a specific minute/second/millis value combination
    @Test
    public void testFromDateFields_specificTime() {
        Calendar calendar = new GregorianCalendar(1985, Calendar.JUNE, 20, 14, 07, 33);
        calendar.set(Calendar.MILLISECOND, 500);
        Date date = calendar.getTime();

        LocalDateTime localDateTime = LocalDateTime.fromDateFields(date);

        assertEquals(1985, localDateTime.getYear());
        assertEquals(DateTimeConstants.JUNE, localDateTime.getMonthOfYear());
        assertEquals(20, localDateTime.getDayOfMonth());
        assertEquals(14, localDateTime.getHourOfDay());
        assertEquals(7, localDateTime.getMinuteOfHour());
        assertEquals(33, localDateTime.getSecondOfMinute());
        assertEquals(500, localDateTime.getMillisOfSecond());
    }

    // Test case 11: Test with a date around midnight to ensure day boundary handling
    @Test
    public void testFromDateFields_midnightDate() {
        Calendar calendar = new GregorianCalendar(2024, Calendar.JANUARY, 1, 0, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);
        Date date = calendar.getTime();

        LocalDateTime localDateTime = LocalDateTime.fromDateFields(date);

        assertEquals(2024, localDateTime.getYear());
        assertEquals(DateTimeConstants.JANUARY, localDateTime.getMonthOfYear());
        assertEquals(1, localDateTime.getDayOfMonth());
        assertEquals(0, localDateTime.getHourOfDay());
        assertEquals(0, localDateTime.getMinuteOfHour());
        assertEquals(0, localDateTime.getSecondOfMinute());
        assertEquals(0, localDateTime.getMillisOfSecond());
    }

    // Test case 12: Test with a date just before midnight
    @Test
    public void testFromDateFields_beforeMidnightDate() {
        Calendar calendar = new GregorianCalendar(2024, Calendar.JANUARY, 1, 23, 59, 59);
        calendar.set(Calendar.MILLISECOND, 999);
        Date date = calendar.getTime();

        LocalDateTime localDateTime = LocalDateTime.fromDateFields(date);

        assertEquals(2024, localDateTime.getYear());
        assertEquals(DateTimeConstants.JANUARY, localDateTime.getMonthOfYear());
        assertEquals(1, localDateTime.getDayOfMonth());
        assertEquals(23, localDateTime.getHourOfDay());
        assertEquals(59, localDateTime.getMinuteOfHour());
        assertEquals(59, localDateTime.getSecondOfMinute());
        assertEquals(999, localDateTime.getMillisOfSecond());
    }
}
