import org.joda.time.MutableDateTime;
import org.joda.time.DateTimeZone;
import org.joda.time.Chronology;
import org.joda.time.chrono.ISOChronology;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTimeAddHoursTest {

    // Test with a positive number of hours
    @Test
    public void testAddPositiveHours() {
        MutableDateTime mdt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        mdt.addHours(5);
        assertEquals(15, mdt.getHourOfDay());
        assertEquals(1, mdt.getDayOfMonth());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(2023, mdt.getYear());
    }

    // Test with a negative number of hours
    @Test
    public void testAddNegativeHours() {
        MutableDateTime mdt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        mdt.addHours(-3);
        assertEquals(7, mdt.getHourOfDay());
        assertEquals(1, mdt.getDayOfMonth());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(2023, mdt.getYear());
    }

    // Test adding hours that cross a day boundary (forward)
    @Test
    public void testAddHoursCrossDayForward() {
        MutableDateTime mdt = new MutableDateTime(2023, 1, 1, 22, 0, 0, 0);
        mdt.addHours(4); // Should go to Jan 2, 02:00
        assertEquals(2, mdt.getHourOfDay());
        assertEquals(2, mdt.getDayOfMonth());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(2023, mdt.getYear());
    }

    // Test adding hours that cross a day boundary (backward)
    @Test
    public void testAddHoursCrossDayBackward() {
        MutableDateTime mdt = new MutableDateTime(2023, 1, 2, 1, 0, 0, 0);
        mdt.addHours(-3); // Should go to Jan 1, 22:00
        assertEquals(22, mdt.getHourOfDay());
        assertEquals(1, mdt.getDayOfMonth());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(2023, mdt.getYear());
    }

    // Test adding a large positive number of hours
    @Test
    public void testAddLargePositiveHours() {
        MutableDateTime mdt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        mdt.addHours(24 * 30 + 5); // 30 days and 5 hours
        assertEquals(5, mdt.getHourOfDay());
        assertEquals(31, mdt.getDayOfMonth());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(2023, mdt.getYear());
    }

    // Test adding a large negative number of hours
    @Test
    public void testAddLargeNegativeHours() {
        MutableDateTime mdt = new MutableDateTime(2023, 2, 1, 0, 0, 0, 0);
        mdt.addHours(-(24 * 30 + 5)); // 30 days and 5 hours backward
        assertEquals(19, mdt.getHourOfDay());
        assertEquals(2, mdt.getDayOfMonth());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(2023, mdt.getYear());
    }

    // Test adding zero hours
    @Test
    public void testAddZeroHours() {
        MutableDateTime mdt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        MutableDateTime originalMdt = mdt.copy();
        mdt.addHours(0);
        assertEquals(originalMdt, mdt); // Should remain unchanged
    }

    // Test with different time zones
    @Test
    public void testAddHoursWithTimeZone() {
        DateTimeZone london = DateTimeZone.forID("Europe/London");
        MutableDateTime mdt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0, london);
        mdt.addHours(2);
        assertEquals(12, mdt.getHourOfDay());
        assertEquals(london, mdt.getZone());
    }

    // Test with different chronologies
    @Test
    public void testAddHoursWithChronology() {
        Chronology gregorian = ISOChronology.getInstanceUTC();
        MutableDateTime mdt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0, gregorian);
        mdt.addHours(1);
        assertEquals(11, mdt.getHourOfDay());
        assertEquals(gregorian, mdt.getChronology());
    }

    // Test adding hours crossing year boundary (forward)
    @Test
    public void testAddHoursCrossYearForward() {
        MutableDateTime mdt = new MutableDateTime(2023, 12, 31, 23, 0, 0, 0);
        mdt.addHours(2); // Should go to Jan 1, 2024, 01:00
        assertEquals(1, mdt.getHourOfDay());
        assertEquals(1, mdt.getDayOfMonth());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(2024, mdt.getYear());
    }

    // Test adding hours crossing year boundary (backward)
    @Test
    public void testAddHoursCrossYearBackward() {
        MutableDateTime mdt = new MutableDateTime(2024, 1, 1, 0, 0, 0, 0);
        mdt.addHours(-1); // Should go to Dec 31, 2023, 23:00
        assertEquals(23, mdt.getHourOfDay());
        assertEquals(31, mdt.getDayOfMonth());
        assertEquals(12, mdt.getMonthOfYear());
        assertEquals(2023, mdt.getYear());
    }

    // Test a very large number of hours to ensure no overflow issues (within int limits)
    @Test
    public void testAddVeryLargeHours() {
        MutableDateTime mdt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        // Add 100 years worth of hours
        int hoursToAdd = 100 * 365 * 24; // Approx, ignoring leap years for simplicity in initial calculation
        mdt.addHours(hoursToAdd);
        // The exact date/time would be complex to assert directly without considering leap years precisely.
        // We can at least check it moved significantly forward and the hour is within bounds.
        assertTrue(mdt.getYear() > 2000);
        assertTrue(mdt.getHourOfDay() >= 0 && mdt.getHourOfDay() < 24);
    }
}
