import org.joda.time.Chronology;
import org.joda.time.DateTimeConstants;
import org.joda.time.DateTimeZone;
import org.joda.time.MutableDateTime;
import org.joda.time.chrono.BuddhistChronology;
import org.joda.time.chrono.GregorianChronology;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class MutableDateTimeAddYearsTest {

    @Test
    public void testAddPositiveYears() {
        MutableDateTime mdt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        mdt.addYears(5);
        assertEquals(2005, mdt.getYear());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(1, mdt.getDayOfMonth());
    }

    @Test
    public void testAddNegativeYears() {
        MutableDateTime mdt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        mdt.addYears(-5);
        assertEquals(1995, mdt.getYear());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(1, mdt.getDayOfMonth());
    }

    @Test
    public void testAddZeroYears() {
        MutableDateTime mdt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        mdt.addYears(0);
        assertEquals(2000, mdt.getYear());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(1, mdt.getDayOfMonth());
    }

    @Test
    public void testAddYearsAcrossLeapYearForward() {
        // February 29th, adding years should adjust to Feb 28th in non-leap years
        MutableDateTime mdt = new MutableDateTime(2000, 2, 29, 0, 0, 0, 0);
        mdt.addYears(1); // 2001 is not a leap year
        assertEquals(2001, mdt.getYear());
        assertEquals(2, mdt.getMonthOfYear());
        assertEquals(28, mdt.getDayOfMonth());

        mdt = new MutableDateTime(2000, 2, 29, 0, 0, 0, 0);
        mdt.addYears(4); // 2004 is a leap year
        assertEquals(2004, mdt.getYear());
        assertEquals(2, mdt.getMonthOfYear());
        assertEquals(29, mdt.getDayOfMonth());
    }

    @Test
    public void testAddYearsAcrossLeapYearBackward() {
        // February 29th, subtracting years should adjust to Feb 28th in non-leap years
        MutableDateTime mdt = new MutableDateTime(2004, 2, 29, 0, 0, 0, 0);
        mdt.addYears(-1); // 2003 is not a leap year
        assertEquals(2003, mdt.getYear());
        assertEquals(2, mdt.getMonthOfYear());
        assertEquals(28, mdt.getDayOfMonth());

        mdt = new MutableDateTime(2004, 2, 29, 0, 0, 0, 0);
        mdt.addYears(-4); // 2000 is a leap year
        assertEquals(2000, mdt.getYear());
        assertEquals(2, mdt.getMonthOfYear());
        assertEquals(29, mdt.getDayOfMonth());
    }

    @Test
    public void testAddLargeNumberOfYearsPositive() {
        MutableDateTime mdt = new MutableDateTime(1, 1, 1, 0, 0, 0, 0);
        mdt.addYears(100000);
        assertEquals(100001, mdt.getYear());
    }

    @Test
    public void testAddLargeNumberOfYearsNegative() {
        MutableDateTime mdt = new MutableDateTime(200000, 1, 1, 0, 0, 0, 0);
        mdt.addYears(-100000);
        assertEquals(100000, mdt.getYear());
    }

    @Test
    public void testAddYearsWithDifferentChronology() {
        Chronology buddhist = BuddhistChronology.getInstance();
        MutableDateTime mdt = new MutableDateTime(2543, 1, 1, 0, 0, 0, 0, buddhist); // 2000 CE in Buddhist
        mdt.addYears(5);
        assertEquals(2548, mdt.getYear()); // 2005 CE
    }

    @Test
    public void testAddYearsToMinDateTime() {
        // Joda-Time can handle dates very far in the past.
        MutableDateTime mdt = new MutableDateTime(-292275000, 1, 1, 0, 0, 0, 0, GregorianChronology.getInstanceUTC());
        mdt.addYears(10);
        assertEquals(-292274990, mdt.getYear());
    }

    @Test
    public void testAddYearsToMaxDateTime() {
        // Joda-Time can handle dates very far in the future.
        MutableDateTime mdt = new MutableDateTime(292278993, 1, 1, 0, 0, 0, 0, GregorianChronology.getInstanceUTC());
        mdt.addYears(-10);
        assertEquals(292278983, mdt.getYear());
    }

    @Test
    public void testAddYearsAcrossCenturyBoundary() {
        MutableDateTime mdt = new MutableDateTime(1999, 12, 31, 0, 0, 0, 0);
        mdt.addYears(1);
        assertEquals(2000, mdt.getYear());
        assertEquals(12, mdt.getMonthOfYear());
        assertEquals(31, mdt.getDayOfMonth());

        mdt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        mdt.addYears(-1);
        assertEquals(1999, mdt.getYear());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(1, mdt.getDayOfMonth());
    }

    @Test
    public void testAddYearsRetainsTimeInformation() {
        MutableDateTime mdt = new MutableDateTime(2000, 1, 1, 10, 20, 30, 400);
        mdt.addYears(3);
        assertEquals(2003, mdt.getYear());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(1, mdt.getDayOfMonth());
        assertEquals(10, mdt.getHourOfDay());
        assertEquals(20, mdt.getMinuteOfHour());
        assertEquals(30, mdt.getSecondOfMinute());
        assertEquals(400, mdt.getMillisOfSecond());
    }

    @Test
    public void testAddYearsToDifferentTimeZone() {
        DateTimeZone chicago = DateTimeZone.forID("America/Chicago");
        MutableDateTime mdt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0, chicago);
        mdt.addYears(1);
        assertEquals(2001, mdt.getYear());
        assertEquals(chicago, mdt.getZone()); // Zone should be retained
    }

    @Test
    public void testAddYearsDoesNotMutateOtherInstances() {
        MutableDateTime original = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        MutableDateTime mdt = new MutableDateTime(original); // Create a copy
        mdt.addYears(5);

        assertEquals(2000, original.getYear()); // Original should be unchanged
        assertEquals(2005, mdt.getYear());
        assertNotEquals(original, mdt);
    }
}
