        mdt.addMonths(2);
        assertEquals(2023, mdt.getYear());
        assertEquals(3, mdt.getMonthOfYear());
        assertEquals(15, mdt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsNegative() {
        MutableDateTime mdt = new MutableDateTime(2023, 3, 15, 10, 0, 0, 0);
        mdt.addMonths(-1);
        assertEquals(2023, mdt.getYear());
        assertEquals(2, mdt.getMonthOfYear());
        assertEquals(15, mdt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsZero() {
        MutableDateTime mdt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0);
        mdt.addMonths(0);
        assertEquals(2023, mdt.getYear());
        assertEquals(1, mdt.getMonthOfYear());
        assertEquals(15, mdt.getDayOfMonth());
    }

