        assertEquals(2023, mdt.getYear());
        assertEquals(2, mdt.getMonthOfYear());
        assertEquals(28, mdt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsEndOfMonthPreservationLeapYear() {
        MutableDateTime mdt = new MutableDateTime(2024, 1, 31, 10, 0, 0, 0); // 2024 is a leap year
        mdt.addMonths(1); // January 31 + 1 month = February 29 (leap year)
        assertEquals(2024, mdt.getYear());
        assertEquals(2, mdt.getMonthOfYear());
        assertEquals(29, mdt.getDayOfMonth());
    }

