        Chronology chronology = ISOChronology.getInstanceUTC();
        MutableDateTime mdt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0, chronology);
        mdt.addMonths(1);
        assertEquals(2023, mdt.getYear());
        assertEquals(2, mdt.getMonthOfYear());
        assertEquals(15, mdt.getDayOfMonth());
