        MutableDateTime mdt = new MutableDateTime(2023, 9, 30, 10, 0, 0, 0); // September has 30 days
        mdt.addMonths(1); // +1 month -> October, which has 31 days. Day should remain 30.
        assertEquals(2023, mdt.getYear());
        assertEquals(10, mdt.getMonthOfYear());
        assertEquals(30, mdt.getDayOfMonth());
