    // Test adding positive amount to various fields
    @Test
    public void testAddPositiveAmount() {
        MutableDateTime mdt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0, ISOChronology.getInstanceUTC());

        mdt.add(DurationFieldType.years(), 1);
        assertEquals(2001, mdt.getYear());

        mdt.add(DurationFieldType.months(), 2);
        assertEquals(3, mdt.getMonthOfYear());

        mdt.add(DurationFieldType.weeks(), 1);
        assertEquals(8, mdt.getDayOfMonth()); // Original day 1 + 1 month + 1 week = March 8th (if day 1 was a Saturday and week starts on Sunday)

        // Reset and test days
        mdt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0, ISOChronology.getInstanceUTC());
        mdt.add(DurationFieldType.days(), 5);
        assertEquals(6, mdt.getDayOfMonth());

        // Reset and test hours
        mdt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0, ISOChronology.getInstanceUTC());
        mdt.add(DurationFieldType.hours(), 3);
        assertEquals(3, mdt.getHourOfDay());

        // Reset and test minutes
        mdt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0, ISOChronology.getInstanceUTC());
        mdt.add(DurationFieldType.minutes(), 10);
