public class PeriodNormalizedStandardTest {

    @Test
    public void testNormalizedStandard_NullPeriodType() {
        // Test with a null PeriodType, should default to standard()
        Period p = new Period(0, 0, 0, 1, 24, 0, 0, 0); // 1 day, 24 hours
        Period normalized = p.normalizedStandard(null);
        assertEquals(new Period(0, 0, 0, 2, 0, 0, 0, 0), normalized); // Should normalize to 2 days
    }

    @Test
    public void testNormalizedStandard_StandardPeriodType_DaysAndHours() {
        // Test with a standard PeriodType, ensuring hours are normalized to days
        Period p = new Period(0, 0, 0, 0, 48, 0, 0, 0); // 48 hours
        Period normalized = p.normalizedStandard(PeriodType.standard());
        assertEquals(new Period(0, 0, 0, 2, 0, 0, 0, 0), normalized); // Should be 2 days
    }

    @Test
    public void testNormalizedStandard_StandardPeriodType_MinutesAndHours() {
        // Test with a standard PeriodType, ensuring minutes are normalized to hours
        Period p = new Period(0, 0, 0, 0, 0, 120, 0, 0); // 120 minutes
        Period normalized = p.normalizedStandard(PeriodType.standard());
        assertEquals(new Period(0, 0, 0, 0, 2, 0, 0, 0), normalized); // Should be 2 hours
    }

    @Test
    public void testNormalizedStandard_StandardPeriodType_SecondsAndMinutes() {
        // Test with a standard PeriodType, ensuring seconds are normalized to minutes
        Period p = new Period(0, 0, 0, 0, 0, 0, 120, 0); // 120 seconds
        Period normalized = p.normalizedStandard(PeriodType.standard());
        assertEquals(new Period(0, 0, 0, 0, 0, 2, 0, 0), normalized); // Should be 2 minutes
    }

    @Test
    public void testNormalizedStandard_StandardPeriodType_MillisecondsAndSeconds() {
        // Test with a standard PeriodType, ensuring milliseconds are normalized to seconds
        Period p = new Period(0, 0, 0, 0, 0, 0, 0, 2000); // 2000 milliseconds
        Period normalized = p.normalizedStandard(PeriodType.standard());
        assertEquals(new Period(0, 0, 0, 0, 0, 0, 2, 0), normalized); // Should be 2 seconds
    }

    @Test
    public void testNormalizedStandard_StandardPeriodType_MixedFields() {
        // Test with a standard PeriodType, mixed fields
        Period p = new Period(0, 13, 1, 8, 26, 65, 61, 1001); // 13 months, 1 week, 8 days, 26 hours, 65 minutes, 61 seconds, 1001 milliseconds
        Period normalized = p.normalizedStandard(PeriodType.standard());
        // Expected: 1 year, 2 months, 2 weeks, 2 days, 3 hours, 6 minutes, 2 seconds, 1 millisecond
        // 13 months -> 1 year 1 month
        // 1 week 8 days -> 15 days -> 2 weeks 1 day (using default week duration)
        // 26 hours -> 1 day 2 hours
        // 65 minutes -> 1 hour 5 minutes
        // 61 seconds -> 1 minute 1 second
        // 1001 millis -> 1 second 1 millis
        // Total: 1 year, 1 month, (1 week + 1 day from original days + 1 day from original hours) = 1 week + 2 days, (2 hours + 1 hour from original minutes) = 3 hours, (5 minutes + 1 minute from original seconds) = 6 minutes, (1 second + 1 second from original millis) = 2 seconds, 1 millisecond
        assertEquals(new Period(1, 2, 2, 2, 3, 6, 2, 1), normalized);
