        PeriodType noDays = PeriodType.time(); // Only hours, minutes, seconds, milliseconds
        Period p = new Period(0, 0, 0, 0, 48, 0, 0, 0); // 48 hours
        Period normalized = p.normalizedStandard(noDays);
        assertEquals(new Period(0, 0, 0, 0, 48, 0, 0, 0, noDays), normalized); // Should remain 48 hours
    }

    @Test
    public void testNormalizedStandard_PeriodTypeWithoutHours() {
