        PeriodType weeksOnly = PeriodType.forFields(new DurationFieldType[]{DurationFieldType.weeks()});
        Period p = new Period(0, 0, 0, 14, 0, 0, 0, 0); // 14 days
        Period normalized = p.normalizedStandard(weeksOnly);
        assertEquals(new Period(0, 0, 2, 0, 0, 0, 0, 0, weeksOnly), normalized); // Should be 2 weeks
    }

    @Test
    public void testNormalizedStandard_PreservesOriginalPeriod() {
        // Ensure the original Period instance is not modified
        Period original = new Period(0, 0, 0, 0, 24, 0, 0, 0);
        Period normalized = original.normalizedStandard(PeriodType.standard());
        assertEquals(new Period(0, 0, 0, 0, 24, 0, 0, 0), original); // Original should be unchanged
        assertEquals(new Period(0, 0, 0, 1, 0, 0, 0, 0), normalized);
    }

    @Test
    public void testNormalizedStandard_LargeMillisecondsOverflow() {
        // Test with a very large number of milliseconds that could potentially overflow if not handled correctly.
        // This is more of a theoretical test for `ArithmeticException` as JodaTime's `long` duration
        // typically handles large values within its range.
        // Long.MAX_VALUE milliseconds
        long largeMillis = Long.MAX_VALUE;
        Period p = Period.millis((int) (largeMillis % Integer.MAX_VALUE)); // A large enough int value
        p = p.plusMillis((int) (largeMillis / Integer.MAX_VALUE)); // Add more in another field to make total large

        // This specific test case is difficult to trigger an ArithmeticException directly from Period#normalizedStandard
        // unless intermediate calculations exceed long's capacity. Joda Time's internal mechanisms generally
        // prevent this for standard scenarios within the period fields.
        // For demonstration, we'll assert that it still produces a valid period.
        try {
            Period normalized = new Period(largeMillis, PeriodType.millis()).normalizedStandard(PeriodType.standard());
            assertNotNull(normalized);
            // The exact value might depend on the Chronology and PeriodType, but it shouldn't crash.
            // For a basic check:
            assertEquals(largeMillis, normalized.toStandardDuration().getMillis());
        } catch (ArithmeticException e) {
            // This is the expected exception for overflow, but might not be triggered by this input
            // due to Joda Time's robust long-based calculations.
            fail("ArithmeticException should not occur for this value within standard period types if handled by long.");
        }
    }
